// Word Ladder — reference solution.
// BFS from `begin`; neighbours are generated by trying all 26 letters at each
// position and removing hits from the unvisited set. Time O(N·L²·26), space O(N·L).

use std::collections::{HashSet, VecDeque};

pub fn ladder_length(begin: &str, end: &str, words: &[&str]) -> Option<usize> {
    let mut unvisited: HashSet<&[u8]> = words.iter().map(|w| w.as_bytes()).collect();
    let target = end.as_bytes();
    if !unvisited.contains(target) {
        return None;
    }
    unvisited.remove(begin.as_bytes());
    let mut queue = VecDeque::from([(begin.as_bytes().to_vec(), 1)]);
    while let Some((mut word, steps)) = queue.pop_front() {
        if word == target {
            return Some(steps);
        }
        for i in 0..word.len() {
            let original = word[i];
            for ch in (b'a'..=b'z').filter(|&ch| ch != original) {
                word[i] = ch;
                if unvisited.remove(&word[..]) {
                    queue.push_back((word.clone(), steps + 1));
                }
            }
            word[i] = original;
        }
    }
    None
}

